//! The serialization vectors for every `delegate.*` row — `koru-events`'s
//! drift defense, kept beside the builders because `koru-events` is a leaf
//! that cannot build a delegate envelope. Regenerated by the same switch:
//! `KORU_UPDATE_EVENTS=1 cargo test -p koru-delegate-events`.

use std::path::Path;

use koru_events::validate;

use super::*;

fn update_requested() -> bool {
    match std::env::var("KORU_UPDATE_EVENTS") {
        Ok(value) => {
            let value = value.trim().to_ascii_lowercase();
            !matches!(value.as_str(), "" | "0" | "false" | "no" | "off")
        }
        Err(_) => false,
    }
}

#[test]
fn the_serialization_vectors_are_current() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/vectors");
    if update_requested() {
        std::fs::create_dir_all(&dir).expect("create tests/vectors");
    }
    for (name, envelope) in every_row() {
        let path = dir.join(format!("{name}.json"));
        let generated = serde_json::to_string_pretty(&envelope).unwrap();
        if update_requested() {
            std::fs::write(&path, format!("{generated}\n")).expect("write vector");
            continue;
        }
        let current = std::fs::read_to_string(&path).unwrap_or_default();
        let current: serde_json::Value = serde_json::from_str(current.trim()).unwrap_or_else(|_| {
            panic!(
                "{} is missing or unreadable; regenerate with `KORU_UPDATE_EVENTS=1 cargo test -p koru-delegate-events`",
                path.display()
            )
        });
        let generated: serde_json::Value = serde_json::from_str(&generated).unwrap();
        assert_eq!(
            current, generated,
            "the wire shape of `{name}` changed; if that is deliberate, bump its version and regenerate with `KORU_UPDATE_EVENTS=1 cargo test -p koru-delegate-events`"
        );
        // And the vector round-trips back into the type and past the boundary.
        let decoded: Envelope = serde_json::from_value(generated).unwrap();
        validate(&decoded).unwrap();
        assert_eq!(decoded, envelope);
    }
}
